'use client';

import React, { useState } from 'react';
import { ProgressBar } from '@/components/ProgressBar';
import { Step0Landing } from '@/components/Step0Landing';
import { Step1BirthMonth } from '@/components/Step1BirthMonth';
import { Step2Intent } from '@/components/Step2Intent';
import { Step3Calculating } from '@/components/Step3Calculating';
import { Step4Result } from '@/components/Step4Result';
import { QuizAnswers, QuizStep } from '@/types/quiz';

export default function QuizFunnelPage() {
  const [step, setStep] = useState<QuizStep>('landing');
  const [answers, setAnswers] = useState<QuizAnswers>({});

  const getProgress = (currentStep: QuizStep): number => {
    switch (currentStep) {
      case 'landing':
        return 5;
      case 'birth-month':
        return 15;
      case 'focus-area':
        return 55;
      case 'calculating':
        return 85;
      case 'result':
        return 100;
      default:
        return 5;
    }
  };

  const handleStep0Continue = () => {
    setStep('birth-month');
    if (typeof window !== 'undefined') {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const handleSelectMonth = (month: string) => {
    setAnswers((prev) => ({ ...prev, birthMonth: month }));
    setStep('focus-area');
    if (typeof window !== 'undefined') {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const handleSelectIntent = (intent: string) => {
    setAnswers((prev) => ({ ...prev, focusArea: intent }));
    setStep('calculating');
    if (typeof window !== 'undefined') {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const handleCalculationComplete = () => {
    setStep('result');
    if (typeof window !== 'undefined') {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const handleRestart = () => {
    setAnswers({});
    setStep('landing');
    if (typeof window !== 'undefined') {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  return (
    <div className="w-full min-h-screen bg-[#FAFAFA] flex flex-col items-center">
      {/* Barra de progresso contínua no topo */}
      <header className="sticky top-0 z-50 w-full bg-[#FAFAFA]/95 backdrop-blur-xs shadow-xs">
        <ProgressBar progress={getProgress(step)} />
      </header>

      {/* Conteúdo dinâmico com transições suaves */}
      <main className="w-full flex-1 flex flex-col justify-start">
        {step === 'landing' && (
          <Step0Landing onContinue={handleStep0Continue} />
        )}

        {step === 'birth-month' && (
          <Step1BirthMonth
            selectedMonth={answers.birthMonth}
            onSelectMonth={handleSelectMonth}
            onBack={() => setStep('landing')}
          />
        )}

        {step === 'focus-area' && (
          <Step2Intent
            selectedMonth={answers.birthMonth || 'Enero'}
            selectedIntent={answers.focusArea}
            onSelectIntent={handleSelectIntent}
            onBack={() => setStep('birth-month')}
          />
        )}

        {step === 'calculating' && (
          <Step3Calculating
            birthMonth={answers.birthMonth || 'Enero'}
            onComplete={handleCalculationComplete}
          />
        )}

        {step === 'result' && (
          <Step4Result
            birthMonth={answers.birthMonth || 'Enero'}
            intent={answers.focusArea}
            onRestart={handleRestart}
          />
        )}
      </main>
    </div>
  );
}
